macro_rules! determine_capture_info {
    () => {
        # [doc = " Helper function to determine if we need to escalate CaptureKind from"] # [doc = " CaptureInfo A to B and returns the escalated CaptureInfo."] # [doc = " (Note: CaptureInfo contains CaptureKind and an expression that led to capture it in that way)"] # [doc = ""] # [doc = " If both `CaptureKind`s are considered equivalent, then the CaptureInfo is selected based"] # [doc = " on the `CaptureInfo` containing an associated `capture_kind_expr_id`."] # [doc = ""] # [doc = " It is the caller's duty to figure out which path_expr_id to use."] # [doc = ""] # [doc = " If both the CaptureKind and Expression are considered to be equivalent,"] # [doc = " then `CaptureInfo` A is preferred. This can be useful in cases where we want to prioritize"] # [doc = " expressions reported back to the user as part of diagnostics based on which appears earlier"] # [doc = " in the closure. This can be achieved simply by calling"] # [doc = " `determine_capture_info(existing_info, current_info)`. This works out because the"] # [doc = " expressions that occur earlier in the closure body than the current expression are processed before."] # [doc = " Consider the following example"] # [doc = " ```rust,no_run"] # [doc = " struct Point { x: i32, y: i32 }"] # [doc = " let mut p = Point { x: 10, y: 10 };"] # [doc = ""] # [doc = " let c = || {"] # [doc = "     p.x += 10; // E1"] # [doc = "     // ..."] # [doc = "     // More code"] # [doc = "     // ..."] # [doc = "     p.x += 10; // E2"] # [doc = " };"] # [doc = " ```"] # [doc = " `CaptureKind` associated with both `E1` and `E2` will be ByRef(MutBorrow),"] # [doc = " and both have an expression associated, however for diagnostics we prefer reporting"] # [doc = " `E1` since it appears earlier in the closure body. When `E2` is being processed we"] # [doc = " would've already handled `E1`, and have an existing capture_information for it."] # [doc = " Calling `determine_capture_info(existing_info_e1, current_info_e2)` will return"] # [doc = " `existing_info_e1` in this case, allowing us to point to `E1` in case of diagnostics."] fn determine_capture_info (capture_info_a : ty :: CaptureInfo , capture_info_b : ty :: CaptureInfo ,) -> ty :: CaptureInfo { let eq_capture_kind = match (capture_info_a . capture_kind , capture_info_b . capture_kind) { (ty :: UpvarCapture :: ByValue , ty :: UpvarCapture :: ByValue) => true , (ty :: UpvarCapture :: ByUse , ty :: UpvarCapture :: ByUse) => true , (ty :: UpvarCapture :: ByRef (ref_a) , ty :: UpvarCapture :: ByRef (ref_b)) => ref_a == ref_b , (ty :: UpvarCapture :: ByValue , _) | (ty :: UpvarCapture :: ByUse , _) | (ty :: UpvarCapture :: ByRef (_) , _) => false , } ; if eq_capture_kind { match (capture_info_a . capture_kind_expr_id , capture_info_b . capture_kind_expr_id) { (Some (_) , _) | (None , None) => capture_info_a , (None , Some (_)) => capture_info_b , } } else { match (capture_info_a . capture_kind , capture_info_b . capture_kind) { (ty :: UpvarCapture :: ByUse , ty :: UpvarCapture :: ByValue) | (ty :: UpvarCapture :: ByValue , ty :: UpvarCapture :: ByUse) => { bug ! ("Same capture can't be ByUse and ByValue at the same time") } (ty :: UpvarCapture :: ByValue , ty :: UpvarCapture :: ByValue) | (ty :: UpvarCapture :: ByUse , ty :: UpvarCapture :: ByUse) | (ty :: UpvarCapture :: ByValue | ty :: UpvarCapture :: ByUse , ty :: UpvarCapture :: ByRef (_)) => { capture_info_a } (ty :: UpvarCapture :: ByRef (_) , ty :: UpvarCapture :: ByValue | ty :: UpvarCapture :: ByUse) => { capture_info_b } (ty :: UpvarCapture :: ByRef (ref_a) , ty :: UpvarCapture :: ByRef (ref_b)) => { match (ref_a , ref_b) { (BorrowKind :: UniqueImmutable | BorrowKind :: Mutable , BorrowKind :: Immutable) | (BorrowKind :: Mutable , BorrowKind :: UniqueImmutable) => capture_info_a , (BorrowKind :: Immutable , BorrowKind :: UniqueImmutable | BorrowKind :: Mutable) | (BorrowKind :: UniqueImmutable , BorrowKind :: Mutable) => capture_info_b , (BorrowKind :: Immutable , BorrowKind :: Immutable) | (BorrowKind :: UniqueImmutable , BorrowKind :: UniqueImmutable) | (BorrowKind :: Mutable , BorrowKind :: Mutable) => { bug ! ("Expected unequal capture kinds") ; } } } } } }
    };
}

determine_capture_info!()